x;flex-wrap:wrap}.work-card-links,.work-inline-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.work-action-menu{position:relative}.work-action-menu>summary{list-style:none;cursor:pointer;border:1px solid #d0d5dd;border-radius:10px;padding:8px 11px;font-size:.78rem;font-weight:800;background:#fff}.work-action-menu>summary::-webkit-details-marker{display:none}.work-action-panel{position:absolute;right:0;z-index:20;width:min(360px,85vw);padding:14px;background:#fff;border:1px solid #d0d5dd;border-radius:14px;box-shadow:0 18px 50px rgba(16,24,40,.18);display:grid;gap:10px}.work-action-panel form{display:grid;grid-template-columns:1fr auto;gap:8px}.work-action-panel input,.work-action-panel select,.work-action-panel textarea{min-width:0}.work-action-panel textarea{grid-column:1/-1;min-height:66px}.work-action-panel .button{align-self:end}.work-overdue{color:#b42318;font-weight:800}.work-timeline{display:grid;gap:12px}.work-timeline article{display:grid;grid-template-columns:12px 1fr;gap:12px}.work-timeline i{width:10px;height:10px;border-radius:50%;margin-top:6px;background:#98a2b3}.work-timeline i.critical,.work-timeline i.failed{background:#d92d20}.work-timeline i.high,.work-timeline i.blocked{background:#f79009}.work-timeline i.completed,.work-timeline i.active{background:#12b76a}.work-timeline p{margin:3px 0;color:#475467}.work-filter{display:grid;grid-template-columns:2fr repeat(4,1fr) auto;gap:10px;align-items:end}.work-filter label span{display:block;font-size:.72rem;font-weight:800;color:#475467;margin-bottom:5px}.work-empty{padding:34px;text-align:center;border:1px dashed #d0d5dd;border-radius:16px;color:#667085}.work-distribution{display:grid;gap:14px}.work-distribution-row{display:grid;grid-template-columns:minmax(130px,1fr) minmax(160px,2fr) 46px;gap:10px;align-items:center}.work-distribution-row strong{font-size:.82rem}.work-bar{height:9px;border-radius:999px;background:#eaecf0;overflow:hidden}.work-bar i{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,#475467,#98a2b3)}.work-rule-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.work-rule-card{border:1px solid #e2e6ee;border-radius:16px;padding:16px;background:#fff}.work-rule-card header{display:flex;justify-content:space-between;gap:12px}.work-rule-card h3{margin:5px 0}.work-rule-card pre{max-height:160px;overflow:auto;border-radius:10px;background:#101828;color:#e4e7ec;padding:11px;font-size:.72rem;white-space:pre-wrap}.work-rule-card dl{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.work-rule-card dt{font-size:.67rem;text-transform:uppercase;color:#667085;font-weight:800}.work-rule-card dd{margin:2px 0 0;font-size:.8rem}.work-rule-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.work-rule-actions form{display:flex;gap:7px;flex-wrap:wrap}.work-rule-actions input{min-width:180px}.work-kpi-list{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.work-kpi-list article{border:1px solid #e4e7ec;border-radius:14px;padding:15px;background:#fff}.work-kpi-list span{font-size:.7rem;color:#667085;text-transform:uppercase;font-weight:800}.work-kpi-list strong{display:block;font-size:1.35rem;margin-top:5px}.work-governance-list{display:grid;gap:10px}.work-governance-list article{border:1px solid #e4e7ec;border-radius:13px;padding:13px;background:#fff}.work-governance-list header{display:flex;justify-content:space-between;gap:12px}.work-governance-list p{margin:6px 0;color:#475467}.work-escalation-level{display:inline-flex;align-items:center;gap:4px;font-size:.72rem;font-weight:800;color:#b42318}.work-source-chip{display:inline-flex;padding:4px 7px;border-radius:999px;background:#eef2ff;color:#3538cd;font-size:.7rem;font-weight:800}@media(max-width:1300px){.work-summary{grid-template-columns:repeat(4,1fr)}.work-meta{grid-template-columns:repeat(3,1fr)}}@media(max-width:900px){.work-command-grid,.work-command-grid.equal,.work-rule-grid{grid-template-columns:1fr}.work-filter{grid-template-columns:1fr 1fr}.work-filter label:first-child{grid-column:1/-1}.work-summary{grid-template-columns:repeat(2,1fr)}.work-meta{grid-template-columns:1fr 1fr}.work-kpi-list{grid-template-columns:1fr}}@media(max-width:560px){.work-meta,.work-filter{grid-template-columns:1fr}.work-card-head{display:block}.work-badges{justify-content:flex-start;margin-top:8px}.work-action-panel{position:fixed;left:12px;right:12px;bottom:12px;width:auto}.work-summary{grid-template-columns:1fr 1fr}}
</style>
HTML;
}

function work_management_render_distribution(array$data):void
{
    $max=max([1,...array_map('intval',array_values($data))]);echo'<div class="work-distribution">';
    foreach($data as$label=>$count){$width=min(100,((int)$count/$max)*100);echo'<div class="work-distribution-row"><strong>'.h(status_label((string)$label)).'</strong><div class="work-bar"><i style="width:'.h(number_format($width,1)).'%"></i></div><b>'.number_format((int)$count).'</b></div>';}
    echo'</div>';
}

function work_management_due_label(array$item):string
{
    if(empty($item['due_at']))return'No due date';
    if(work_management_item_overdue($item)){$minutes=(int)floor((time()-strtotime((string)$item['due_at']))/60);return$minutes>=1440?number_format($minutes/1440,1).' days overdue':number_format(max(1,$minutes/60),1).' hours overdue';}
    $seconds=strtotime((string)$item['due_at'])-time();return$seconds>=86400?number_format($seconds/86400,1).' days remaining':number_format(max(0,$seconds/3600),1).' hours remaining';
}

function work_management_render_action_menu(array$item):void
{
    $user=current_user();if(!$user)return;$canAct=work_management_item_can_act($item,$user);$canAssign=work_management_can('assign',$user);$isReviewer=(int)($item['reviewer_id']??0)===(int)$user['id'];$isApprover=(int)($item['approver_id']??0)===(int)$user['id'];if(!$canAct&&!$canAssign&&!$isReviewer&&!$isApprover)return;
    $actionUrl=app_url('work-management-action.php');$return='work-management.php?tab='.query_string('tab','overview').'&q='.rawurlencode((string)$item['work_number']);echo'<details class="work-action-menu"><summary>Actions</summary><div class="work-action-panel">';
    $form=function(string$action,string$label,string$class='secondary',bool$note=true)use($item,$actionUrl,$return):void{echo'<form action="'.h($actionUrl).'" method="post">'.csrf_field().'<input type="hidden" name="action" value="'.h($action).'"><input type="hidden" name="work_item_id" value="'.(int)$item['id'].'"><input type="hidden" name="return_to" value="'.h($return).'">';if($note)echo'<textarea name="evidence_note" required placeholder="Governance evidence for this action"></textarea>';echo'<button class="button '.h($class).'" type="submit">'.h($label).'</button></form>';};
    if($item['status']==='open'&&$canAct)$form(empty($item['assigned_user_id'])?'claim_item':'start_item',empty($item['assigned_user_id'])?'Claim & Start':'Start','primary');
    if($item['status']==='blocked'&&$canAct)$form('resume_item','Resume','primary');
    if(in_array($item['status'],['open','in_progress','waiting_review','waiting_approval'],true)&&$canAct)$form('block_item','Block','ghost');
    if($item['status']==='in_progress'&&$canAct){if(!empty($item['reviewer_id'])||!empty($item['approver_id']))$form('submit_review','Submit for Review','primary');else$form('complete_item','Complete','primary');}
    if($item['status']==='waiting_review'&&$isReviewer)$form('review_item',empty($item['approver_id'])?'Review & Complete':'Approve Review','primary');
    if($item['status']==='waiting_approval'&&$isApprover)$form('approve_item','Final Approval','primary');
    if($canAssign&&!in_array($item['status'],['completed','cancelled'],true)){echo'<form action="'.h($actionUrl).'" method="post">'.csrf_field().'<input type="hidden" name="action" value="reassign_item"><input type="hidden" name="work_item_id" value="'.(int)$item['id'].'"><input type="hidden" name="return_to" value="'.h($return).'"><select name="assigned_user_id" required>'.user_options($item['assigned_user_id']).'</select><textarea name="evidence_note" required placeholder="Reason for reassignment"></textarea><button class="button secondary" type="submit">Reassign</button></form>';$form('escalate_item','Escalate','secondary');}
    echo'</div></details>';
}

function work_management_render_item(array$item):void
{
    $origin=work_management_entity((int)$item['entity_id']);$assigned=!empty($item['assigned_entity_id'])?work_management_entity((int)$item['assigned_entity_id']):null;
    echo'<article class="work-card priority-'.h($item['priority']).'" id="work-'.(int)$item['id'].'"><div class="work-card-head"><div><span class="work-number">'.h($item['work_number']).'</span><h3>'.h($item['title']).'</h3><small>'.h($origin['entity_name']??data_company_name($item['company_id'])).'</small></div><div class="work-badges">'.badge($item['priority']).badge($item['status']).'<span class="work-source-chip">'.h(status_label($item['source_module'])).'</span></div></div>';
    echo'<p>'.h($item['description']).'</p><div class="work-meta"><div><span>Owner</span><strong>'.h(data_user_name($item['assigned_user_id']??null)).'</strong></div><div><span>Assigned entity</span><strong>'.h($assigned['entity_name']??'External / unassigned').'</strong></div><div><span>Required permission</span><strong>'.h($item['required_permission']).'</strong></div><div><span>Due</span><strong class="'.(work_management_item_overdue($item)?'work-overdue':'').'">'.h(work_management_due_label($item)).'</strong></div><div><span>Governance</span><strong>'.h(data_user_name($item['reviewer_id']??null)).(!empty($item['approver_id'])?' → '.h(data_user_name($item['approver_id'])):'').'</strong></div></div>';
    echo'<div class="work-card-footer"><div class="work-card-links"><a class="button ghost" href="'.h(work_management_source_link($item)).'">Open Source</a><a class="button ghost" href="'.h(app_url('agent.php?prompt='.rawurlencode('Explain the evidence, blocker, owner, SLA, and next permitted action for '.$item['work_number'].'.'))).'">Analyze</a>';
    if((int)$item['escalation_level']>0)echo'<span class="work-escalation-level">Escalation L'.(int)$item['escalation_level'].'</span>';echo'</div>';work_management_render_action_menu($item);echo'</div></article>';
}

function work_management_render_queue(array$items,string$empty='No work items match this view.'):void
{
    if(!$items){echo'<div class="work-empty">'.h($empty).'</div>';return;}echo'<div class="work-queue">';foreach($items as$item)work_management_render_item($item);echo'</div>';
}
